// Generated by scripts/generate-content.mjs before each production build.
export const DOC_FILES: Record<string, string> = {
  "company": "---\ntitle: About Prismelo\ndescription: What Prismelo.tech is, how the company is structured, and which facts are confirmed for publication.\nstatus: Published\n---\n\nPrismelo.tech is a technology and cybersecurity company. It builds and operates software, cloud infrastructure and applied AI systems, and provides security assessment and advisory work.\n\n## Confirmed company information\n\n| Field | Value |\n| --- | --- |\n| Company name | Prismelo.tech |\n| Founder | Kunal Purohit |\n| Focus | Technology, cybersecurity, software engineering, cloud infrastructure, AI |\n| Website | [prismelo.tech](https://prismelo.tech) |\n| Owned company | HirenextAI — [hirenextai.com](https://hirenextai.com) |\n| Contact | [hello@prismelo.tech](mailto:hello@prismelo.tech) |\n\nThis table is intentionally short. It contains only information that has been confirmed for publication.\n\n## What the company does\n\nPrismelo works across the layers a modern business depends on:\n\n- **Application engineering** — custom software, web platforms and APIs.\n- **Security** — authorized penetration testing, security architecture and risk advisory.\n- **Infrastructure** — cloud planning, deployment, hosting architecture and reliability.\n- **Applied AI** — features, integrations and workflow automation with measurable outcomes.\n\nClient work and product work run alongside each other. HirenextAI is the group's active product company.\n\n## How the company is organised\n\nPrismelo is the parent company. Products and subsidiaries keep their own identity, domain and product direction, while drawing on the same engineering and security practice.\n\nNo further companies are announced. New entities are added to the [companies page](/companies) only when they exist.\n\n## What is not published\n\nThe following are deliberately absent from this documentation and the website:\n\n- employee counts and founding dates\n- office locations\n- certifications and audit attestations\n- client names and case studies\n- revenue, funding and financial information\n\nWhere any of these becomes confirmed and appropriate to publish, it will appear here with a source.\n\n<Callout title=\"Corrections\" tone=\"note\">\n  If something on this website is inaccurate, email [hello@prismelo.tech](mailto:hello@prismelo.tech). Corrections take priority over new content.\n</Callout>\n",
  "company/brand": "---\ntitle: Brand & naming\ndescription: Prismelo's name usage, logo rules, colour system and typography.\nstatus: Published\n---\n\nThis page is for anyone producing material that carries the Prismelo name — proposals, documentation, product pages or partner collateral.\n\n## Name usage\n\n| Context | Correct | Incorrect |\n| --- | --- | --- |\n| Full name | Prismelo.tech | Prismelo Tech, PrismeloTech |\n| Wordmark | PRISMELO with .TECH | Prismelo.tech in all caps |\n| In running text | Prismelo | PRISMELO |\n| Possessive | Prismelo's | Prismelos |\n\nUse **Prismelo.tech** the first time the name appears in a formal document. After that, **Prismelo** is sufficient.\n\n## The symbol\n\nThe Prismelo symbol is an abstract loop formed from three rounded segments. It is drawn as a single-colour vector.\n\n- White symbol on black backgrounds.\n- Black symbol on white backgrounds when required.\n- Do not recolour, outlined-version, skew, add strokes or re-draw the symbol.\n- Do not place the symbol on photography or gradients.\n- Keep clear space of at least the symbol's width on all sides.\n\nThe symbol is used in the navigation, footer, favicon and loading states. It should not be accompanied by a container, badge or icon treatment.\n\n## Colour\n\nThe system is strictly monochrome.\n\n| Token | Value | Use |\n| --- | --- | --- |\n| Base | `#000000` | Page background |\n| Ink | `#FFFFFF` | Primary text |\n| Muted | `#A0A0A0` | Secondary text |\n| Line | `#252525` | Borders and rules |\n| Surface | `#0A0A0A` | Cards and panels |\n\nNo accent colours, gradients or neon treatments are used in brand material. If a diagram needs to show a distinction, use value — line weight, fill lightness, or dashing — rather than hue.\n\n## Typography\n\nGeist is the primary typeface, with Geist Mono used for labels, code and data. When Geist is unavailable, Inter is the permitted substitute.\n\n- Headings are medium weight with tight tracking; they are never bold-heavy.\n- Section labels are uppercase, small, with wide tracking.\n- Body text is neutral grey on black; primary statements may be white.\n- Line length is held to a comfortable measure — long paragraphs are a misuse.\n\n## Voice\n\nWrite plainly and specifically. Prefer a concrete statement to a superlative. Avoid claiming leadership, disruption or guaranteed outcomes. If a capability is emerging, describe what exists today.\n\n## Assets\n\nLogo files are available on request from [hello@prismelo.tech](mailto:hello@prismelo.tech). Product brands in the group — currently HirenextAI — are governed by their own brand guidelines.\n",
  "company/legal": "---\ntitle: Legal & policies\ndescription: Where Prismelo's privacy policy, terms of service and confidentiality practices are documented.\nstatus: Published\n---\n\n## Policies published on this site\n\n- [Privacy Policy](/privacy) — what data this website processes, why, and how to request deletion.\n- [Terms of Service](/terms) — the terms governing use of this website.\n\nThese pages describe the website. Client engagements are governed by a separate written agreement, which takes precedence for that work.\n\n## Confidentiality\n\nEnquiries, engagements and assessment material are treated as confidential by default. Prismelo can work under a client NDA, and can provide a mutual confidentiality agreement where one is required before technical detail is exchanged.\n\nConfidentiality expectations for security work — including handling of findings and evidence — are recorded in the rules of engagement for each assessment.\n\n## Intellectual property\n\nCode, documentation and configuration produced during an engagement are assigned to the client as set out in the engagement agreement. In the absence of a specific clause, the default position is full transfer on final payment.\n\nPrismelo retains ownership of its brand, documentation templates, internal tooling and any pre-existing components, which may be licensed for use within the delivered system.\n\n## Data handling\n\nThis website's contact form processes the information you submit in order to respond to your enquiry. Where delivery email is configured, submissions are transmitted to Prismelo through a transactional email provider.\n\n- No analytics profiles are built from form submissions.\n- Submission data is not sold or shared for marketing.\n- Retention follows the engagement: enquiry records are kept only as long as needed to handle the conversation and any resulting work.\n\nThe [Privacy Policy](/privacy) contains the full detail.\n\n## Security reports\n\nSecurity issues in Prismelo-operated systems should be reported through the [responsible disclosure](/docs/services/security-disclosure) process, not through general support channels.\n\n## Not legal advice\n\nThis documentation is operational guidance, not legal advice. Contractual questions should be directed to the contact named in your engagement agreement.\n",
  "faqs": "---\ntitle: Frequently asked questions\ndescription: Common questions about working with Prismelo, security engagements and this website.\nstatus: Published\n---\n\n## Working with Prismelo\n\n### Do you work with early-stage companies?\n\nYes. We work with companies at different stages, including projects that are still being defined. What matters is that the problem is real and the decision-maker is involved.\n\n### Do you take on maintenance of an existing codebase?\n\nYes. We start with a short review to understand what exists, then agree the highest-value work. Rewrites are proposed only when maintaining the current system is genuinely riskier.\n\n### Who owns the work?\n\nYou do. Code, documentation and configuration are delivered in your repositories and assigned under the engagement agreement.\n\n## Security work\n\n### Do you need written authorization to test?\n\nYes — always. Testing does not begin until a signed scope and authorization document exists. See [Assessment scope & authorization](/docs/services/penetration-testing).\n\n### Can you test a site you do not own on someone's behalf?\n\nOnly with documented authorization from the system owner. We will ask for it, and decline the work if it cannot be provided.\n\n### Do you issue security certifications?\n\nNo. Certification is issued by accredited auditors. We can help prepare and close gaps, and we will be clear about where an external auditor is required.\n\n### Do you provide 24/7 monitoring?\n\nNo. We can design logging, alerting and incident procedures for the team or provider that operates them.\n\n## AI work\n\n### Can you guarantee a model will be accurate?\n\nNo. We measure accuracy on your workload, set thresholds, and design the product so uncertain outputs are visible. Any claim of guaranteed accuracy should be treated with suspicion.\n\n### Where does our data go when you build an AI feature?\n\nThat is agreed explicitly before implementation: which provider, which retention settings, and what is sent. Where required, we design around providers with suitable terms or keep processing on your own infrastructure.\n\n## This website\n\n### Is the community forum live?\n\nNo. The interface is complete, but no backend is connected. Content shown there is sample data and is labelled as such. The required integration contract is documented in [Community integration](/docs/guides/community-integration).\n\n### Does the contact form work?\n\nIt validates and accepts submissions. Delivery requires a transactional email provider to be configured — until then the form reports that delivery is not configured and offers a mailto fallback, rather than showing a false success. See [Contact form integration](/docs/guides/contact-form-integration).\n\n### Are the blog articles real?\n\nThe articles under [/resources](/resources) are sample content published to demonstrate the format. They are labelled as sample articles and are not company announcements.\n\n## Commercial\n\n### How is pricing set?\n\nPer engagement, after scoping. The scope document states what is included and what the work will cost before it begins.\n\n### Can we start small?\n\nYes, and we usually recommend it. A short advisory or a narrow first deliverable is the cheapest way to test whether a larger engagement makes sense.\n",
  "getting-started": "---\ntitle: Introduction\ndescription: The principles behind how Prismelo works with clients, and what to expect from an engagement.\nstatus: Published\n---\n\nPrismelo is a technology and cybersecurity company. We work on software, cloud infrastructure, applied AI and security — usually in combination, because systems do not respect those boundaries.\n\nThis page explains the working model. The [engagement process](/docs/getting-started/engagement-process) page covers the sequence in detail.\n\n## What an engagement looks like\n\nMost work begins with a conversation about a problem rather than a spec. From that we produce a short written scope: what will be delivered, what is explicitly excluded, what we need from your side, and how success will be judged.\n\nThat document matters. It is the reference for every subsequent decision, including the ones that change direction.\n\n<Callout title=\"Small scope, honest scope\" tone=\"note\">\n  We would rather define a narrow engagement we can finish well than a broad one that produces partially-finished work. Scope can grow later, deliberately.\n</Callout>\n\n## Principles we work to\n\n### Clarity before complexity\n\nThe simplest structure that meets the requirement is the one that survives contact with a real team. Complexity is added when it buys something specific — not because it is available.\n\n### Security as a property\n\nSecurity is a property of how a system is designed, built and operated. It is not a review that happens at the end, and it is not a document.\n\n### Evidence over assertion\n\nClaims about performance, reliability or accuracy should be measurable. Where something is not yet proven — an AI use case, a migration outcome — we say so and propose how to test it.\n\n### Ownership after handover\n\nWork is complete when your team can operate, extend and explain the system without us in the room. That is why documentation is a deliverable, not an extra.\n\n## What we need from you\n\n- A decision-maker who can confirm scope.\n- Access to the systems, repositories or environments in scope — or a plan for how access will be provided.\n- An honest account of constraints: timeline, budget, existing commitments and team capacity.\n- A technical contact who can review work as it is delivered.\n\n## Where to go next\n\n- [Engagement process](/docs/getting-started/engagement-process) — phases, deliverables and change control.\n- [Contact & communication](/docs/getting-started/contact) — how to reach us and what to include.\n- [Services overview](/docs/services) — the seven service areas in detail.\n",
  "getting-started/contact": "---\ntitle: Contact & communication\ndescription: How to reach Prismelo, what to include in a first message, and how to report a security issue.\nstatus: Published\n---\n\n## Channels\n\n**Website form** — [/contact](/contact) is the preferred route for new enquiries. It asks for the information needed to respond usefully.\n\n**Email** — [hello@prismelo.tech](mailto:hello@prismelo.tech) for general enquiries, existing engagements and documentation corrections.\n\n**Security issues** — do not use the general form. Follow the [responsible disclosure](/docs/services/security-disclosure) process so the report reaches the right place.\n\n## What to include in a first message\n\nA useful first message answers four things:\n\n- **The problem** — what is happening now, and what should be happening instead.\n- **The system** — what exists today: stack, hosting, team, constraints.\n- **The timeline** — any fixed date, and what it depends on.\n- **The decision** — who needs to approve the work.\n\nYou do not need a specification. A few clear paragraphs are more useful than a template.\n\n## Response\n\nWe aim to reply to enquiries as soon as practical. If a request falls outside what we do, we will say so directly and, where possible, point to the kind of specialist who can help.\n\n## During an engagement\n\nCommunication runs through an agreed channel for the duration of the work: a shared project space, email thread or scheduled call. For security assessments, an escalation contact and out-of-hours number are recorded in the rules of engagement before testing starts.\n\n## Confidentiality\n\nMaterial shared during an enquiry is treated as confidential by default. We can work under your NDA, and can provide a mutual agreement where one is required before technical detail is exchanged.\n",
  "getting-started/engagement-process": "---\ntitle: Engagement process\ndescription: The phases of a Prismelo engagement, from scoping through handover, and how changes are handled.\nstatus: Published\n---\n\nEvery engagement is scoped individually, but the shape is consistent. It exists to keep scope honest and progress visible.\n\n## Phases\n\n<Steps items={[\n  { title: \"Discovery\", body: \"A short conversation and, where useful, a review of existing systems. The objective is to understand the problem, the constraints and the decision that needs making.\" },\n  { title: \"Written scope\", body: \"A document covering deliverables, exclusions, assumptions, access requirements, timing and the criteria for completion. This is the reference for the rest of the work.\" },\n  { title: \"Delivery\", body: \"Work proceeds in reviewable increments. For builds, that means working software and a running environment early. For assessments, it means interim findings before the final report.\" },\n  { title: \"Review\", body: \"Each increment is reviewed against the agreed criteria. Findings or defects are handled before the next increment, not accumulated at the end.\" },\n  { title: \"Handover\", body: \"Documentation, a walkthrough session and an agreed support period so your team can own the result.\" }\n]} />\n\n## Change control\n\nScope changes are normal. They are handled explicitly:\n\n1. The change is described in writing — what is added, removed or adjusted.\n2. The effect on timing and cost is stated.\n3. Work continues on the agreed scope until the change is accepted.\n\nNothing is quietly absorbed into the schedule. If an addition would compromise the delivery date, we will say so before it happens.\n\n## What completion means\n\nAn engagement is complete when the agreed deliverables exist, have been reviewed against the scope, and have been handed over with documentation. For security assessments, that includes the findings register and the remediation walkthrough. For builds, it includes the repository, environment configuration and handover notes.\n\n<Callout title=\"When we would stop\" tone=\"note\">\n  If an evaluation shows that a proposed approach will not work — an AI use case without sufficient data, a rewrite that is riskier than the existing system — we will report that rather than continue to bill against a conclusion that has changed.\n</Callout>\n\n## Timing\n\nTimelines are agreed per engagement after scoping. Estimates are based on the defined scope; where a delivery date depends on a third party (a vendor, an approval, an infrastructure provider), that dependency is stated in the scope document rather than assumed.\n\n## Documentation as part of delivery\n\nWritten output is produced during the work, not reconstructed at the end. Architecture decisions, assessment findings and operating procedures are recorded as they are made, which is also why the handover is a conversation about documents that already exist.\n",
  "guides/community-integration": "---\ntitle: Community integration\ndescription: The data model, API contract and authentication requirements needed to connect the community frontend to a live backend.\nstatus: Published\n---\n\nThe community section at [/community](/community) is implemented as a complete frontend over a clearly defined data layer. This page documents the current state and the exact integration points required to make it live.\n\n<Callout title=\"Current state\" tone=\"draft\">\n  There is no production backend connected to the community pages. Discussions, comments and profiles shown in the interface are **sample content**, labelled as such in the UI. Reading works against seeded data; authentication-gated actions open an explicit \"accounts are not available yet\" notice instead of simulating a write.\n</Callout>\n\n## What exists today\n\n| Capability | State |\n| --- | --- |\n| Browse categories | Implemented, reads `lib/community.ts` |\n| Read discussions and comments | Implemented, seeded data |\n| Search and sort | Implemented, client-side filter |\n| Public profiles | Implemented, seeded data |\n| Create discussion / comment | Gated UI, no persistence |\n| Vote / bookmark / report | Gated UI, no persistence |\n\n## Data model\n\nA backend implementation should provide at minimum the following entities.\n\n```sql\ncreate table profiles (\n  id            text primary key,      -- from the auth provider subject\n  username      text unique not null,\n  display_name  text not null,\n  bio           text,\n  created_at    timestamptz not null default now()\n);\n\ncreate table discussions (\n  id            uuid primary key default gen_random_uuid(),\n  category_slug text not null,\n  author_id     text not null references profiles(id),\n  title         text not null,\n  body          text not null,\n  created_at    timestamptz not null default now(),\n  reply_count   integer not null default 0,\n  score         integer not null default 0\n);\n\ncreate table comments (\n  id            uuid primary key default gen_random_uuid(),\n  discussion_id uuid not null references discussions(id) on delete cascade,\n  author_id     text not null references profiles(id),\n  parent_id     uuid references comments(id) on delete cascade,\n  body          text not null,\n  created_at    timestamptz not null default now()\n);\n```\n\nVotes, bookmarks and reports follow the same pattern: a join table keyed by `(user_id, target_id)`, with a uniqueness constraint that makes repeat actions idempotent.\n\n## API contract\n\n```ts\n// GET /api/community/discussions?category=security&q=token&sort=latest&page=1\ntype DiscussionListResponse = {\n  items: {\n    id: string;\n    slug: string;\n    title: string;\n    excerpt: string;\n    category: string;\n    author: { username: string; displayName: string };\n    createdAt: string;\n    replyCount: number;\n    score: number;\n  }[];\n  total: number;\n  page: number;\n};\n```\n\nWrite endpoints:\n\n| Method | Path | Auth | Purpose |\n| --- | --- | --- | --- |\n| `POST` | `/api/community/discussions` | Required | Create discussion |\n| `POST` | `/api/community/discussions/:id/comments` | Required | Reply |\n| `POST` | `/api/community/discussions/:id/vote` | Required | Idempotent vote |\n| `POST` | `/api/community/discussions/:id/bookmark` | Required | Idempotent bookmark |\n| `POST` | `/api/community/reports` | Required | Report content |\n\n## Authentication requirements\n\nAny write endpoint must:\n\n1. Resolve the session server-side and derive `author_id` from the session subject. Never accept a user id from the request body.\n2. Reject requests whose `Origin` does not match the site origin.\n3. Validate and length-limit every text field before storing it.\n4. Return `401` for anonymous writes and `403` for authenticated users without permission.\n5. Keep personal data out of logs.\n\nRead endpoints can remain public, but must not expose email addresses or moderation metadata.\n\n## Example server check\n\n```ts\nexport async function POST(request: Request) {\n  const session = await requireSession(request); // your auth integration\n  if (!session) return Response.json({ error: \"unauthorized\" }, { status: 401 });\n\n  if (!isSameOrigin(request)) {\n    return Response.json({ error: \"forbidden\" }, { status: 403 });\n  }\n\n  const body = await request.json();\n  const parsed = createDiscussionSchema.safeParse(body);\n  if (!parsed.success) {\n    return Response.json({ error: \"validation_failed\" }, { status: 400 });\n  }\n\n  const discussion = await db.discussions.create({\n    ...parsed.data,\n    authorId: session.user.id, // derived, never supplied by the client\n  });\n\n  return Response.json({ discussion }, { status: 201 });\n}\n```\n\n## Replacing the sample data\n\nThe seeded data lives in one module, `lib/community.ts`. To connect a backend:\n\n1. Replace the exported read helpers with server-side fetches to the endpoints above.\n2. Pass the resolved user session into the discussion detail and composer components.\n3. Replace the gated action notices with real mutations, including optimistic vote updates and error rollback.\n4. Add loading and empty states for each fetch — the components already accept them.\n5. Remove the \"sample content\" label from the UI once live data is in place.\n\n## Interface states\n\nThe frontend already implements empty search results, skeleton loading routes and error boundaries. When a backend is connected, keep those states rather than collapsing them into a single \"nothing here\" view — a failed request and an empty result should not look the same.\n",
  "guides/contact-form-integration": "---\ntitle: Contact form integration\ndescription: How the Prismelo contact form validates and delivers submissions, and how to configure email delivery.\nstatus: Published\n---\n\nThe contact form posts to a server route at `/api/contact`. Validation, spam rejection and delivery all happen server-side. Without delivery configuration the route reports that honestly rather than pretending a message was sent.\n\n## Request contract\n\n```ts\ntype ContactRequest = {\n  name: string;      // required, 2–80 characters\n  email: string;     // required, RFC-shaped\n  company?: string;  // optional, max 120 characters\n  service?: string;  // optional, one of the service labels\n  details: string;   // required, 20–4000 characters\n  website?: string;  // honeypot, must be empty\n};\n```\n\n## Responses\n\n| Status | Body | Meaning |\n| --- | --- | --- |\n| `200` | `{ \"ok\": true }` | Accepted and delivered |\n| `400` | `{ \"error\": \"validation_failed\", \"fields\": {...} }` | Field-level validation failed |\n| `429` | `{ \"error\": \"rate_limited\" }` | Too many submissions from one address |\n| `501` | `{ \"error\": \"delivery_not_configured\" }` | No email provider configured |\n| `502` | `{ \"error\": \"delivery_failed\" }` | Provider rejected the message |\n\nWhen the route returns `501`, the interface shows an explicit notice and a mailto fallback containing the submitted text. It does not show a success state.\n\n## Environment variables\n\n```bash\n# SMTP relay (Brevo) — port 587 uses STARTTLS, port 465 uses implicit TLS\nSMTP_HOST=smtp-relay.brevo.com\nSMTP_PORT=587\nSMTP_USER=your-relay-login@smtp-brevo.com\nSMTP_PASS=your-smtp-key\n\n# Verified sender address at the relay\nCONTACT_FROM_EMAIL=\"Prismelo Website <website@prismelo.tech>\"\n\n# Destination for enquiries — keep private\nCONTACT_TO_EMAIL=hello@prismelo.tech\n```\n\nSet these in the deployment environment. They are server-only: none are prefixed with `NEXT_PUBLIC_`, and none are read in client components.\n\n## Delivery implementation\n\nAll outgoing mail goes through `lib/mailer.ts`, which holds one pooled\n`nodemailer` transport. The route does not talk to a provider directly:\n\n```ts\nconst delivery = await deliverMail({\n  to: process.env.CONTACT_TO_EMAIL,\n  replyTo: payload.email,\n  subject: `Website enquiry — ${payload.service ?? \"General\"}`,\n  text: renderPlainText(payload),\n});\n```\n\n`deliverMail` returns one of three outcomes — delivered, not configured, or\nfailed with the relay's message — so a caller can never claim a send that did\nnot happen. The sender address is `CONTACT_FROM_EMAIL` (or `EMAIL_FROM`), and\nthe SMTP login is only used if neither is set. Whatever address you send from\nmust be a verified sender or domain at the relay, or Brevo rejects the message.\n\n## What the email looks like\n\nEvery message is rendered by `renderEmail` in `lib/email.ts` as a 600px\ntable-based layout with inline styles, so it survives Gmail, Apple Mail and\nOutlook without a stylesheet:\n\n- **Header** — the Prismelo mark and wordmark on the brand black, with a lime\n  rule underneath. The mark is `public/email-logo.png`, a raster copy of\n  `app/icon.svg` (email clients cannot render SVG), sent as an inline `cid:`\n  attachment so the header still shows when remote images are blocked.\n- **Body** — an optional kicker, the heading, paragraphs, an optional field\n  table, and a bordered block containing the full submitted message with its\n  paragraph breaks intact.\n- **Action** — one button. For enquiries it opens a reply addressed to the\n  visitor, so answering needs one click rather than a copy-paste.\n- **Footer** — the reason the message arrived, then the company name, the\n  website and the contact address as links.\n\nEnquiries pass `details` and `quote`; community and policy notifications use\nthe same shell without them.\n\n## Test it locally\n\n```bash\ncurl -i -X POST http://localhost:3000/api/contact \\\n  -H \"Content-Type: application/json\" \\\n  -d '{\n    \"name\": \"Test Contact\",\n    \"email\": \"test@example.com\",\n    \"service\": \"Penetration Testing\",\n    \"details\": \"This is a validation test for local development.\"\n  }'\n```\n\nWithout delivery configuration, expect `501` and the honest interface state. With configuration, expect `200` and a message at `CONTACT_TO_EMAIL`.\n\n## Security notes\n\n- Validation runs on the server; client-side validation is a convenience only.\n- The honeypot field rejects naive bots without a CAPTCHA.\n- Rate limiting is in-memory and per instance. In a multi-instance deployment, enforce it at the platform or edge layer instead.\n- Submitted content is never interpolated into HTML without escaping.\n- The destination address is never exposed to the browser.\n\n## Integration point\n\nIf you are extending this site, the only file that needs to change for a different delivery provider is `lib/mailer.ts`. The contact route, the community notifications and the legal-update notices all share it, and the form component treats delivery as opaque.\n",
  "guides/content-architecture": "---\ntitle: Documentation architecture\ndescription: How articles, navigation, tables of contents and search are generated in this documentation portal.\nstatus: Published\n---\n\nThis documentation is MDX-driven. Articles live as files, navigation is declared as data, and the portal derives tables of contents, previous/next links and the search index from those two sources.\n\n## Directory layout\n\n```text\ncontent/docs/\n  overview.mdx\n  getting-started.mdx\n  getting-started/\n    contact.mdx\n    engagement-process.mdx\n  company/\n    brand.mdx\n  services/\n    penetration-testing.mdx\n  guides/\n    contact-form-integration.mdx\nlib/\n  docs.ts\napp/docs/[[...slug]]/page.tsx\n```\n\n## Frontmatter\n\nEach article begins with a small frontmatter block:\n\n```mdx\n---\ntitle: Assessment scope & authorization\ndescription: Authorization, scoping and rules-of-engagement requirements.\nstatus: Published\n---\n```\n\n`title` and `description` populate the page header, metadata and search index. `status` is either `Published` or `Placeholder`, and is shown as a label in the article header — placeholders are visibly marked rather than silently incomplete.\n\n## Navigation\n\nThe sidebar tree is declared explicitly in `lib/docs.ts`:\n\n```ts\nexport const DOC_NAV = [\n  {\n    title: \"Getting started\",\n    items: [\n      { title: \"Introduction\", slug: \"getting-started\" },\n      { title: \"Engagement process\", slug: \"getting-started/engagement-process\" },\n    ],\n  },\n];\n```\n\nOrdering is intentional rather than alphabetical, and article titles in the sidebar can differ from the H1 where a shorter label reads better.\n\n## Adding an article\n\n1. Create the MDX file at the path matching its slug.\n2. Add an entry to the relevant group in `DOC_NAV`.\n3. Run the build. The route is generated from the navigation list; no dynamic registry is maintained by hand.\n\n## Tables of contents\n\nHeadings are extracted from the source at render time: level-two headings become the right-hand table of contents, and level three appears as an indent where present. Anchor ids are generated by `rehype-slug`, and the scroll-tracking component highlights the section currently in view.\n\nCode fences are skipped during extraction, so a `##` inside a code block will not appear in the TOC.\n\n## Search\n\nThe search index is built from the navigation list, frontmatter and extracted headings — no external service is required. The dialog supports `Cmd`/`Ctrl` + `K`, arrow-key navigation and `Enter` to open the highlighted result.\n\n## Custom components\n\nThree components are available inside articles:\n\n```mdx\n<Callout title=\"Authorization is not optional\" tone=\"warning\">\n  Testing requires written approval.\n</Callout>\n\n<Steps items={[\n  { title: \"Discovery\", body: \"Understand the problem.\" },\n  { title: \"Scope\", body: \"Agree what is included.\" }\n]} />\n\n<CodeBlock language=\"ts\" code=\"const answer = 42;\" />\n```\n\n`Callout` tones are `note`, `warning` and `draft`. Code blocks rendered from fences automatically gain the copy control.\n\n## Writing conventions\n\n- Use `##` for sections that belong in the table of contents; avoid skipping levels.\n- Keep paragraphs short; documentation is scanned before it is read.\n- Prefer concrete examples over descriptions of examples.\n- Mark unconfirmed detail as a placeholder instead of filling the gap with plausible text.\n",
  "overview": "---\ntitle: Documentation overview\ndescription: How Prismelo's documentation is organised, what each section covers, and how to use it.\nstatus: Published\n---\n\nThis documentation describes Prismelo as a company, how our services are scoped and delivered, and the technical conventions behind the systems we build.\n\nIt is written for three audiences: clients evaluating or working with us, engineers integrating with our work, and anyone maintaining a system we have handed over.\n\n## How this documentation is organised\n\n- **Getting started** covers the practical shape of an engagement — how work begins, how it is scoped and how communication runs.\n- **Company information** holds the facts about Prismelo: what the company is, how the brand is used, and where legal policies live.\n- **Services** documents each service area and the rules that apply to security work.\n- **Products** covers companies and products operated within the Prismelo group.\n- **Technical guides** are implementation notes for engineers working on Prismelo-built systems.\n- **FAQs** answers the questions that come up most often before an engagement.\n\n## Status labels\n\nEvery page carries a status. Most are **Published** and describe current practice. A page marked **Placeholder** exists to hold a defined place in the structure while the underlying detail is still being confirmed — it will say so at the top of the article.\n\n<Callout title=\"What this documentation does not contain\" tone=\"note\">\n  We do not publish invented specifications, unverified certifications, client names, or performance statistics. If a detail is missing, it is because it has not been confirmed for publication.\n</Callout>\n\n## Conventions used here\n\nCommand examples assume a POSIX shell. Code samples are written in TypeScript unless a different language is stated. Field names appearing in examples — environment variables, request bodies — match the implementation in this website's repository.\n\n## A note on security documentation\n\nTesting methodology, internal runbooks and client-specific architecture are not published on the open web. Those documents are shared within an engagement, under confidentiality terms where required. The [responsible disclosure](/docs/services/security-disclosure) page explains how to report a security issue.\n\n## Getting help\n\nFor anything not covered here, [contact Prismelo](/contact) or email [hello@prismelo.tech](mailto:hello@prismelo.tech). Documentation corrections are genuinely welcome — if a page is wrong or unclear, tell us which one.\n",
  "products": "---\ntitle: Products overview\ndescription: Companies and products operated within the Prismelo group.\nstatus: Published\n---\n\nPrismelo builds client systems and operates its own companies. This section documents the products in the group.\n\n## Current products\n\n| Product | Industry | Status | Relationship |\n| --- | --- | --- | --- |\n| [HirenextAI](https://hirenextai.com) | AI / Recruitment technology | Active | Owned and operated by Prismelo |\n\nHirenextAI is a company within the Prismelo group. It has its own name, domain and product direction, and product documentation is published by HirenextAI itself.\n\n## Not announced\n\nNo further products or subsidiaries are announced. Names, logos and dates are not published ahead of a real launch — so if something is not on this page, it does not exist publicly yet.\n\n## Products in the group versus client work\n\nClient systems remain the client's property. Products in the group are built, owned and operated by Prismelo. The two share engineering standards and security practice, which is deliberate: product work keeps the practice sharp, and client work exposes it to different constraints.\n\n## Product documentation\n\nEach product maintains its own documentation and support route. For HirenextAI, see the [product page](/docs/products/hirenextai) for the relationship and where to find product information.\n",
  "products/hirenextai": "---\ntitle: HirenextAI\ndescription: HirenextAI's relationship to Prismelo, its status, and where to find its product information.\nstatus: Published\n---\n\nHirenextAI is an AI and recruitment technology company within the Prismelo group.\n\n## Facts\n\n| Field | Value |\n| --- | --- |\n| Name | HirenextAI |\n| Website | [hirenextai.com](https://hirenextai.com) |\n| Industry | AI / Recruitment technology |\n| Status | Active |\n| Relationship | Owned by Prismelo |\n\nHirenextAI is not a client of Prismelo and not a discontinued project. It is an active company operated within the group.\n\n## Where product information lives\n\nProduct features, pricing, availability and support for HirenextAI are published by HirenextAI at [hirenextai.com](https://hirenextai.com). This documentation covers the group relationship and the engineering context, not the product's own specification.\n\n<Callout title=\"Product detail is not duplicated here\" tone=\"note\">\n  Duplicating product documentation across two sites creates drift. If a detail is not covered here, the authoritative source is the product's own website.\n</Callout>\n\n## Engineering context\n\nHirenextAI is built on the same engineering and security practice used for client work: typed application code, reviewed infrastructure configuration, and explicit handling of personal data. Recruitment technology processes sensitive candidate information, so data handling and access control are treated as product requirements rather than afterthoughts.\n\n## Contact\n\n- Product and commercial enquiries: through [hirenextai.com](https://hirenextai.com)\n- Group and engineering enquiries: [hello@prismelo.tech](mailto:hello@prismelo.tech)\n",
  "services": "---\ntitle: Services overview\ndescription: The seven Prismelo service areas, their scope, and how engagements are structured.\nstatus: Published\n---\n\nPrismelo delivers seven service areas. Each has a dedicated page on the main website with scope, process, deliverables and FAQs.\n\n| Service | Primary output | Typical engagement |\n| --- | --- | --- |\n| [Penetration Testing](/services/penetration-testing) | Findings register + remediation guidance | Scoped project |\n| [Cybersecurity Consulting](/services/cybersecurity-consulting) | Risk map + prioritized roadmap | Assessment or advisory |\n| [Cloud & Hosting](/services/cloud-hosting) | Architecture + runbook | Advisory or build |\n| [Software Development](/services/software-development) | Shipped software + documentation | Project or retainer |\n| [AI Solutions](/services/ai-solutions) | Integration + evaluation results | Discovery, then build |\n| [Web Development](/services/web-development) | Launched site or platform | Design & build |\n| [IT Consulting](/services/it-consulting) | Written assessment | Short advisory |\n\n## Engagement models\n\n**Advisory** — a defined question, reviewed and answered in writing. Useful before committing to a build or a migration.\n\n**Assurance** — an authorized security assessment with validated findings. The output is evidence, not opinion.\n\n**Build** — design and delivery of software, infrastructure or an AI integration, with documentation and handover.\n\n## How scope is set\n\nFor every service the same rule applies: what is included, what is excluded, and what completion looks like are agreed in writing before work starts. The [engagement process](/docs/getting-started/engagement-process) page describes how changes are handled.\n\n## Security work has additional requirements\n\nPenetration testing and security assessment work require explicit written authorization from the system owner, an agreed scope and rules of engagement. See [Assessment scope & authorization](/docs/services/penetration-testing) before requesting a test.\n\n<Callout title=\"What we do not offer\" tone=\"note\">\n  Prismelo does not currently sell a public hosting product, does not operate a 24/7 monitoring service, and does not issue security certifications. Related advisory work is available; the distinction is stated on each service page.\n</Callout>\n\n## Choosing between services\n\nIf you are unsure where to start, describe the problem rather than the service. A short advisory engagement is often the cheapest way to decide whether you need a build, a test, an architecture change — or nothing at all.\n",
  "services/penetration-testing": "---\ntitle: Assessment scope & authorization\ndescription: The authorization, scoping and rules-of-engagement requirements that apply to every Prismelo security assessment.\nstatus: Published\n---\n\nPrismelo performs security testing only where there is explicit, documented authorization from the system owner. This page describes what that requires in practice and how an assessment is scoped.\n\n<Callout title=\"Authorization is not optional\" tone=\"warning\">\n  We do not test systems we have not been authorized to test, and we do not begin active testing before written approval is in place. Requests to test a third party's systems without their consent will be declined.\n</Callout>\n\n## Before testing begins\n\nThe following must be confirmed in writing:\n\n1. **Authorizing party** — a named individual with authority over the systems in scope.\n2. **Targets** — exact domains, IP ranges, applications and environments.\n3. **Exclusions** — anything that must not be touched, including third-party services and shared infrastructure.\n4. **Rules of engagement** — permitted techniques, prohibited techniques, test accounts, and data handling.\n5. **Timing** — testing windows, blackout periods and change freezes.\n6. **Contacts** — a technical contact and an escalation contact reachable during testing.\n\nA scope and authorization document is signed by both parties before any active testing occurs.\n\n## Environments\n\nTesting usually runs against a staging environment that mirrors production. Production testing is possible where it is genuinely necessary, but it is scoped more tightly: restricted techniques, agreed windows and your team on standby.\n\n## Methodology, in outline\n\n| Phase | Activity |\n| --- | --- |\n| Reconnaissance | Map surface area, roles, integrations and data flows |\n| Authentication | Session handling, credential flows, MFA behavior, password policy in practice |\n| Authorization | Horizontal and vertical access checks between users, roles and tenants |\n| Input handling | Injection classes, deserialization, file handling, template evaluation |\n| Business logic | Abuse of intended workflows, state transitions, limits and quotas |\n| Validation | Manual reproduction and false-positive removal |\n\nTechniques with a realistic chance of disruption — denial-of-service, destructive actions, social engineering, physical access — are excluded unless separately authorized and lawful.\n\n## Severity\n\nFindings carry a severity derived from CVSS as a reference, adjusted for reachability, required access and business context. Each finding records the affected component, evidence, reproduction steps, impact and recommended remediation.\n\nPriority is a separate axis from severity: a medium-severity issue in an internet-facing authentication path may warrant faster action than a high-severity issue requiring local access.\n\n## Reporting\n\nThe report contains:\n\n- an executive summary for non-technical stakeholders\n- a findings register with evidence and reproduction steps\n- remediation guidance specific to the observed stack\n- a prioritized remediation sequence\n\nInterim critical findings are communicated during the engagement rather than held for the final report.\n\n## Retesting\n\nRetesting of remediated findings is included where agreed in scope. The retest confirms the specific reported issues; it is not a full re-assessment unless separately scoped.\n\n## Documentation not published here\n\nDetailed test plans, payload libraries, internal tooling and client-specific reports are not published. They are shared within an engagement, under confidentiality terms where required.\n",
  "services/security-disclosure": "---\ntitle: Responsible disclosure\ndescription: How to report a security vulnerability affecting Prismelo-operated systems, and what to expect.\nstatus: Published\n---\n\nIf you believe you have found a security issue in a Prismelo-operated system, we want to hear about it.\n\n## Scope\n\n**In scope**\n\n- Web properties served on prismelo.tech\n- Services and APIs operated directly by Prismelo\n\n**Out of scope**\n\n- Third-party services and platforms we use\n- Systems belonging to companies in the group that operate their own properties — report those directly to the relevant company\n- Findings that require physical access, social engineering or insider access\n- Denial-of-service testing, load testing and automated scanning that degrades service\n- Reports generated solely by a scanner without a demonstrated impact\n\n## How to report\n\nEmail [hello@prismelo.tech](mailto:hello@prismelo.tech) with the subject line **SECURITY DISCLOSURE**. Include:\n\n1. The affected URL or component.\n2. A description of the issue and its potential impact.\n3. Reproduction steps, with requests or screenshots where useful.\n4. Whether the issue has been disclosed elsewhere.\n\nIf you need to send evidence over an encrypted channel, say so in a first message without attachments and we will arrange a method.\n\n<Callout title=\"Please do not\" tone=\"warning\">\n  Do not access, modify, download or store data that is not yours. Do not disrupt service. Do not test against accounts you do not own. Stop and report as soon as you have enough evidence to demonstrate the issue.\n</Callout>\n\n## What happens next\n\n- We acknowledge receipt and confirm whether the report is in scope.\n- We investigate and, where confirmed, plan remediation.\n- We keep you informed of meaningful progress.\n- With your agreement, we credit the reporter once the issue is resolved.\n\nPrismelo does not currently operate a paid bounty programme. Reports are nonetheless taken seriously and handled as a priority.\n\n## Safe harbour\n\nWhere a report is made in good faith, within the scope above, and without privacy violations or service disruption, Prismelo will not pursue legal action in relation to the research. This does not authorize testing of systems outside the stated scope.\n\n## Timing\n\nPlease allow reasonable time for remediation before public disclosure. We will agree a disclosure date with you and will not ask for indefinite silence — if remediation is complex, we will tell you what is happening and when to expect a fix.\n"
};

export const RESOURCE_FILES: Record<string, string> = {
  "case-for-boring-infrastructure": "---\ntitle: The case for boring infrastructure\ndescription: A small team operating four components will outperform a small team that inherited twelve.\ncategory: Infrastructure\ndate: 2026-09-30\n---\n\nThere is a particular kind of infrastructure diagram that appears whenever a small service is deployed: load balancer, two container services, a managed queue, a cache, three databases and a CDN. Each component has a reasonable justification. Together they exceed the team's ability to operate them.\n\n## Complexity is an operating cost\n\nEvery component adds failure modes, upgrade paths, access policies, dashboards and alerts. The cost is not the monthly bill — it is the attention required to keep it working and the knowledge required to debug it at an inconvenient hour.\n\nA team that understands four components will run them well. A team that inherited twelve will operate all of them adequately at best, and one of them badly.\n\n## A defensible baseline\n\nFor a small internal service, a reasonable starting point looks like this:\n\n- one runtime, with a documented deploy process\n- one managed relational database\n- backups, with a restore that has actually been performed\n- logs and basic metrics in one place\n- TLS and a sensible access policy\n\nThat is a genuinely reliable system for many workloads. It is also small enough that a new engineer can hold it in their head within a week.\n\n## Add components for a failure mode\n\nThe rule we use: a new component must name the failure mode it addresses. Not \"scalability\" in the abstract, but \"the worker process dies under a burst of uploads, so the job needs to be durable and retried elsewhere\".\n\nNaming the failure mode does three things. It justifies the operational cost, it defines what to monitor, and it gives a future engineer permission to remove the component if the failure mode disappears.\n\n## Make the boring parts visible\n\nInfrastructure that is genuinely dependable is quiet, which makes it easy for stakeholders to assume nothing is happening. Documentation helps:\n\n- a diagram with the components and their data flows\n- a runbook for routine tasks and known incidents\n- a restore procedure with the date it was last tested\n- a note on what is deliberately not implemented, and why\n\nThat last item is underrated. Writing down \"we do not have multi-region failover because the recovery objective is four hours\" prevents the same conversation every quarter.\n\n## When boring is wrong\n\nThis is not an argument for under-engineering. Systems with genuine availability requirements, regulatory constraints or heavy burst loads need the components that meet them. The distinction is whether the complexity is demanded by the workload or inherited from a template.\n\nThe test is not \"is this modern?\" It is \"can the people who operate this explain why each part exists?\"\n",
  "component-system-that-survives-rebrand": "---\ntitle: Designing a component system that survives a rebrand\ndescription: A monochrome design system is easy to restyle only if the tokens were real from the beginning.\ncategory: Design\ndate: 2026-10-16\n---\n\nMost design systems are a component library with a colour palette attached. That works until the palette changes, at which point the team discovers that half the interface was styled by hand and the \"system\" was a naming convention.\n\n## Tokens before components\n\nThe useful abstraction boundary is not the button. It is the value the button consumes.\n\nA small token set covers more than it seems:\n\n- **surface** — page, panel, raised panel\n- **ink** — primary text, secondary text, disabled text\n- **line** — hairline borders, dividers\n- **space** — a consistent scale, not arbitrary pixel values\n- **radius** — one or two values, used consistently\n- **motion** — duration and easing, defined once\n\nWith those in place, a monochrome identity is nearly a configuration. Without them, every section is a small act of design judgement that will not survive contact with a second author.\n\n```css\n@theme {\n  --color-base: #000000;\n  --color-surface: #0a0a0a;\n  --color-line: #252525;\n  --color-ink: #ffffff;\n  --color-muted: #a0a0a0;\n  --ease-out-quint: cubic-bezier(0.22, 1, 0.36, 1);\n}\n```\n\n## One type scale, applied strictly\n\nEditorial layouts live or die on hierarchy. A fluid scale — `clamp` for display sizes, fixed sizes for body — keeps a page composed at every viewport without a breakpoint for each heading.\n\nThe discipline that matters is refusing local overrides. The moment one section uses 23px because it looked better, the scale is decorative rather than structural.\n\n## Layout primitives, not layout wrappers\n\nTwo primitives cover most of a corporate site:\n\n- a **shell** that owns horizontal rhythm and maximum width\n- a **section** that owns vertical rhythm and optional border treatment\n\nEverything else composes those. It sounds restrictive, and that restriction is the point: pages differ in composition, not in spacing logic.\n\n## Motion as a token\n\nMotion should be one or two behaviours — a short reveal, a hover transition — with a single easing curve. Multiple durations and easings used ad hoc read as inconsistency even when nobody can name it.\n\nRespect `prefers-reduced-motion` at the token level, not per component. Then every animation inherits the correct behaviour, including the ones added later by someone else.\n\n## What actually survives\n\nA rebrand changes colour and type. If those were tokens, it is an afternoon. If they were values scattered across two hundred files, it is a quarter.\n\nThe test is simple: change the token file and see what breaks. Anything that breaks was never part of the system.\n",
  "measuring-an-ai-feature": "---\ntitle: Measuring an AI feature before you build it\ndescription: If you cannot describe the baseline and the failure cost, you are not ready to build an AI feature.\ncategory: AI\ndate: 2026-10-08\n---\n\nThe most expensive AI feature is the one that ships, appears to work, and slowly degrades in a way nobody measures. Most of that risk is decided before any code is written — in whether a baseline and a failure cost were defined.\n\n## Start with the current process\n\nWrite down what happens today, even if the answer is \"a person reads the email and types it into the system\".\n\n- How long does the task take?\n- What is the error rate?\n- What does an error cost, and who catches it?\n- How many examples per day, week or month?\n\nWithout these numbers, \"the AI is good\" is not a claim anyone can evaluate. With them, a modest model that matches the human baseline is a real improvement, and a fluent model that is wrong twice as often is a visible regression.\n\n## Define the failure cost honestly\n\nSome tasks tolerate error. Drafting a summary does. Extracting an amount from an invoice and writing it to a ledger does not. The design follows from that distinction:\n\n- **Tolerable errors** — generate, show, let a human accept or edit.\n- **Costly errors** — extract, then validate against an independent rule before writing.\n- **Unrecoverable errors** — do not automate the write; automate the preparation only.\n\nAn AI feature that quietly encodes a costly error as tolerable is a liability, however good the demo looks.\n\n## Build the evaluation set first\n\nA small set of real examples — a hundred is often enough to start — with agreed correct answers. This is the least glamorous part of the work and the only part that tells you whether the feature is ready.\n\n```ts\ntype EvalCase = {\n  id: string;\n  input: string;\n  expected: string;\n  severity: \"tolerable\" | \"costly\";\n};\n\ntype EvalResult = {\n  id: string;\n  output: string;\n  correct: boolean;\n  latencyMs: number;\n};\n```\n\nTwo numbers matter: pass rate on the set, and pass rate weight-adjusted by severity. A model that is 95% accurate overall but fails half the costly cases is not ready, whatever the headline number says.\n\n## Measure the retrieval separately\n\nFor retrieval-augmented systems, most quality problems are retrieval problems wearing a generation costume. Check whether the right document was retrieved before blaming the model for a poor answer. If a human with the same retrieved context could answer correctly, the retrieval is adequate and the generation step needs work.\n\n## Plan the operating cost\n\nToken spend, latency and review time all scale with usage. A feature that costs nothing to demo can be expensive at volume. Model routing, caching and a smaller model for the easy majority are engineering decisions, not optimisations to defer.\n\n## The stopping condition\n\nBefore building, agree what result would make you stop. If the evaluation shows no improvement over the baseline, that should be a successful experiment — not a reason to lower the bar until the project can be declared a win.\n\nThat single agreement prevents more disappointing AI projects than any technical choice.\n",
  "reading-a-penetration-test-report": "---\ntitle: Reading a penetration test report as an engineer\ndescription: The findings register is the least interesting part. The useful work is in reachability, evidence and the fix.\ncategory: Security\ndate: 2026-09-22\n---\n\nA penetration test report usually arrives as a PDF with a severity chart on page two. The chart is a poor guide to what to do. Reading the report well is a separate skill from commissioning it.\n\n## Ignore the headline severity first\n\nSeverity in a report has been calculated for a generic reader. Your system is not generic. Read each finding's evidence and ask three questions:\n\n1. Is the affected component reachable from the internet, or only from an internal network?\n2. What access does exploitation require — anonymous, a standard user, an administrator?\n3. What is the actual data behind it, and is that data sensitive in your context?\n\nAn issue marked high in a service that holds only public reference data ranks below a medium in the authentication path. This is not a reason to dismiss the high finding; it is a reason to sequence deliberately.\n\n## Check the evidence before the recommendation\n\nA finding without a reproducible request is a hypothesis. Reproduce it, or ask the assessor to demonstrate it. Most good reports include the request, the response and the state that made it possible.\n\nWhere reproduction fails, find out why. It is usually one of three things:\n\n- The environment differs from the one tested.\n- The test account had permissions a real user would not have.\n- The finding was generated by a scanner and not validated by hand.\n\nOnly the third is a problem with the assessment. The first two are useful information about your environments.\n\n## Read the fix as a design question\n\nRemediation advice is written against the observed implementation, which makes it a starting point rather than an instruction. A recommendation to \"add authorization checks in the handler\" may be correct and still be the wrong fix if authorization belongs in one place rather than twelve.\n\nTake each recommended fix and ask where the corresponding control should live. If the answer is \"everywhere\", the architecture is the finding.\n\n## Look for what is missing\n\nReports describe what was found, not what was not. Read the scope section carefully for what was excluded: authenticated areas, specific API versions, mobile clients, third-party integrations.\n\nAn assessment that quietly excluded the half of the system you were most worried about is not a clean bill of health.\n\n## Close the loop with a retest\n\nRemediation is complete when the specific exploit no longer works, not when the ticket is closed. Where a fix is structural — moving authorization into a middleware layer, for example — the retest should attempt the bypass, not only the original request.\n\n## A short checklist\n\n- Reproduce every finding before scheduling work.\n- Rank by reachability and data sensitivity, not severity alone.\n- Ask where each control belongs.\n- Read the exclusions.\n- Retest the exploit, and attempt the variant.\n\nA report is a set of arguments. Treat it the way you would treat a design review: with interest in the reasoning and a willingness to disagree.\n",
  "staging-environment-penetration-tests": "---\ntitle: Why your staging environment makes penetration tests lie\ndescription: Staging never mirrors production exactly. Recording the differences is what keeps an assessment honest.\ncategory: Security\ndate: 2026-10-24\nfeatured: true\n---\n\nA penetration test is an argument about what is possible. Like any argument, it is only as good as its premises. When the assessment runs against a staging environment, one of those premises — that what was tested resembles what you run — needs to be examined rather than assumed.\n\n## The gap, in practice\n\nStaging environments diverge from production in ways that quietly change exploitability:\n\n- A web application firewall exists in production and not in staging.\n- Network segmentation differs, so an internal service is reachable in one environment and not the other.\n- The identity provider is a test tenant with different session lifetimes and group mappings.\n- Data is a sanitised subset, so a query that returns two rows in staging returns two hundred thousand in production.\n- Debug endpoints are enabled in staging because they are convenient.\n\nNone of these make the test worthless. They make it conditional, and conditions belong in the report.\n\n## What we record\n\nBefore testing, we produce an environment delta table as part of the scope document. For each relevant control, we note whether it exists in the tested environment, in production, or both.\n\n| Control | Staging | Production | Effect on findings |\n| --- | --- | --- | --- |\n| WAF | Absent | Present | Exploitability in production unconfirmed |\n| Segmentation | Flat | Private subnets | Lateral movement likely overstated |\n| Identity provider | Test tenant | Production tenant | Session findings may differ |\n| Data volume | Subset | Full | Impact understated |\n\nThis takes perhaps an hour to assemble with the client's technical contact. It prevents several hours of disagreement later.\n\n## Separate severity from reachability\n\nThe most useful habit we have adopted is refusing to blend these two properties.\n\n**Severity** describes the demonstrated impact of an issue in the environment where it was confirmed. **Reachability** describes how confidently that impact transfers to production, given the deltas above.\n\nA high-severity issue with low reachability confidence is not a medium-severity issue. It is a high-severity issue that needs one more check before it is scheduled. Collapsing the two makes the register easier to read and less useful to act on.\n\n## Retesting in the right place\n\nIf a finding only reproduces in staging, the retest should confirm the fix in staging and, where possible, verify the control in production separately. Closing a ticket on the basis of a staging retest is normal practice — the caveat is knowing that is what happened.\n\n## A note on production testing\n\nTesting production has its own risks, but it removes the largest caveat in the report. Where it is safe to do so — read-only verification of a specific finding, within an agreed window, with the client's team available — it is often worth more than testing a staging environment twice.\n\nThe decision is a trade between operational risk and evidential strength. Making it explicitly, in the scope document, is the difference between an assessment that informs decisions and one that starts an argument.\n"
};
